    const int stages[3] = { 18, 12, 8 };
    for (int i = 0; i < 3; ++i) {
        if (s.assassinDist > stages[i]) {
            if (Term(s)) { --s.timersLive; return; }
            while (!(s.assassinDist < stages[i])) { Frame(s); if (Term(s)) { --s.timersLive; return; } }
            if (Term(s)) { --s.timersLive; return; }
            ++s.shouts;
        }
    }
    ++s.removed;
    --s.timersLive;
}
